"""Validation script for webhook_endpoint.py."""
import ast
import sys

MODULE = "webhook_endpoint.py"


def main() -> int:
    # 1. Syntax check
    with open(MODULE, "r", encoding="utf-8") as fh:
        source = fh.read()
    tree = ast.parse(source, filename=MODULE)
    print(f"OK: {MODULE} parses cleanly")

    # 2. Structural checks against the skill's webhook requirements
    handler_names = {
        node.name
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    required = {
        "handle_payment_succeeded",
        "handle_payment_failed",
        "stripe_webhook",
        "is_event_processed",
        "mark_event_processed",
    }
    missing = required - handler_names
    if missing:
        print(f"FAIL: missing required handlers: {sorted(missing)}")
        return 1
    print("OK: required handlers present:", sorted(required))

    # 3. Check that event types are dispatched
    dispatched = {
        node.value.value
        for node in ast.walk(tree)
        if isinstance(node, ast.Constant)
        and isinstance(node.value, str)
        and node.value.startswith("payment_intent.")
    }
    expected = {"payment_intent.succeeded", "payment_intent.payment_failed"}
    if not expected.issubset(dispatched):
        print(f"FAIL: expected events not dispatched: {expected - dispatched}")
        return 1
    print("OK: dispatch covers:", sorted(expected))

    # 4. Check signature verification usage
    if not any(isinstance(node, ast.Call) for node in ast.walk(tree)):
        pass
    src_snippet = source
    checks = [
        ("stripe.Webhook.construct_event", "signature verification"),
        ("Stripe-Signature", "signature header read"),
        ("webhook", "route declared"),
    ]
    for needle, label in checks:
        if needle not in src_snippet:
            print(f"FAIL: missing {label} ({needle!r})")
            return 1
        print(f"OK: {label} present ({needle!r})")

    print("ALL CHECKS PASSED")
    return 0


if __name__ == "__main__":
    sys.exit(main())
